import json

DATA = [{'region': 'North', 'amount': '120.50'}, {'region': 'South', 'amount': '80'}, {'region': 'North', 'amount': '39.50'}, {'region': 'South', 'amount': 'N/A'}, {'region': 'West', 'amount': '200.00'}, {'region': 'West', 'amount': ' -20 '}, {'region': 'North', 'amount': ''}, {'region': 'South', 'amount': '100.00'}]

valid_rows = 0
rejected_rows = 0
total = 0.0
by_region = {}

for row in DATA:
    try:
        amount = float(row['amount'].strip())
        if amount == 0 and row['amount'] != '0':
            rejected_rows += 1
        else:
            valid_rows += 1
            total += amount
            region = row['region']
            if region not in by_region:
                by_region[region] = 0.0
            by_region[region] += amount
    except ValueError:
        rejected_rows += 1

by_region_sorted = sorted(by_region.items(), key=lambda x: (-x[1], x[0]))
top_region = by_region_sorted[0][0]

result = {
    'total': round(total, 2),
    'valid_rows': valid_rows,
    'rejected_rows': rejected_rows,
    'by_region': {region: round(amount, 2) for region, amount in by_region.items()},
    'top_region': top_region
}

print(json.dumps(result))

